.ds-specimen{font-family:Arial,'Helvetica Neue',sans-serif;font-size:14px;line-height:1.5;color:var(--text, #1e2c41);}
h2{margin: 0;}
.ds-camera-card{min-width: 0;
  padding: 16px;
  border: 1px solid var(--border, #e0e6ee);
  border-radius: 8px;
  background: var(--surface, #fff);
  color: var(--text, #1e2c41);
  text-align: left;}
.ds-camera-header{display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 10px 20px;
  margin-bottom: 16px;}
.ds-camera-name{min-width: 0;
  margin: 0;
  font-family: inherit;
  font-size: 17px;
  line-height: 1.4;
  font-weight: 650;
  letter-spacing: -0.015em;
  overflow-wrap: anywhere;}
.ds-camera-metadata{display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px 20px;
  color: var(--text-muted, #536277);
  font-size: 12px;
  line-height: 1.5;}
.ds-camera-state{display: inline-flex;
  align-items: center;
  gap: 7px;
  font-weight: 600;}
.ds-camera-state-dot{width: 8px;
  height: 8px;
  flex: none;
  border-radius: 50%;
  background: currentColor;}
.ds-camera-state--unavailable{color: var(--text-muted, #536277);}
.ds-camera-frame-time{white-space: nowrap;}
.ds-camera-frame-time{font-variant-numeric: tabular-nums;}
.ds-camera-preview{position: relative;
  isolation: isolate;
  display: grid;
  overflow: hidden;
  width: 100%;
  aspect-ratio: 1.83;
  border-radius: 3px;
  background: #1d2c3f;}
.ds-camera-loading{grid-area: 1 / 1;
  z-index: 1;
  align-self: center;
  justify-self: center;
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding: 18px 48px 18px 18px;
  color: #fff;
  text-align: center;
  font-size: 14px;
  line-height: 1.5;
  overflow-wrap: anywhere;}
.ds-camera-loading{color: #e0e7ee;}
@media (max-width: 640px){.ds-camera-card{padding: 12px;}
.ds-camera-header{gap: 6px;
    margin-bottom: 12px;}
.ds-camera-metadata{width: 100%;
    gap: 5px 14px;}}

