button:focus-visible{outline: 3px solid #2563eb; outline-offset: 3px;}
button{touch-action: manipulation;}
.ds-event-table-scroll{overflow: auto; border: 1px solid var(--border, #e0e6ee); border-radius: 5px; min-height: 246px;}
.ds-event-table{width: 100%; border-collapse: collapse; text-align: left; font-size: 12px;}
.ds-event-table th{font-weight: 400; color: #415571; padding: 14px 12px; height: 46px; background: #fcfdff; white-space: nowrap;}
.ds-event-table td{height: 57px; padding: 12px; border-top: 1px solid #e5eaf2; white-space: nowrap;}
.ds-event-table tbody tr{cursor: pointer; transition: background-color 150ms ease-out;}
.ds-event-table tbody tr:hover{background: #f2f6fd;}
.ds-event-table tbody tr.ds-is-selected{background: var(--selection, #e2ebff);}
.ds-event-table tbody tr.ds-is-selected td,.ds-event-table tbody tr.ds-is-selected + tr td{border-top-color: #bfd1f8;}
.ds-event-time-button{padding: 6px 2px; margin: -6px -2px; background: none; border: 0; color: #243c63; font: inherit; text-align: left; border-radius: 3px; font-variant-numeric: tabular-nums; min-height: 32px;}
.ds-event-time-button:hover{color: #174fb2; text-decoration: underline; text-underline-offset: 3px;}
@media (min-width: 1550px){.ds-event-table{font-size: 13px;}
.ds-event-table td{height: 59px;}}
@media (max-width: 1350px){.ds-event-table td,.ds-event-table th{padding-inline: 10px;}}
@media (max-width: 1080px){.ds-event-table{font-size: 11px;}}
@media (max-width: 900px){.ds-event-table{font-size: 12px;}}
@media (max-width: 700px){.ds-event-table{min-width: 530px;}}
@media (max-width: 540px){.ds-event-table-scroll{min-height: 236px;}}
@media(prefers-reduced-motion:reduce){.ds-specimen *{transition-duration:.01ms!important;}}

