.ds-sentinel-media-surface{background: #1e293b;
  color: #f8fafc;
  overflow: hidden;
  border-radius: 4px;}
.ds-sentinel-media-button{display: inline-grid;
  place-items: center;
  width: 40px;
  height: 44px;
  padding: 0;
  border: 0;
  border-radius: 4px;
  color: inherit;
  background: transparent;
  cursor: pointer;}
